// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

import { CompactEIP712 } from "@rhinestone/compact-utils/src/common/CompactEIP712.sol";
import { CompactIntentExecutor } from "./CompactIntent/CompactIntentExecutor.sol";
import { Constants } from "@rhinestone/compact-utils/src/types/Constants.sol";
import { ERC7579ExecutorBase } from "modulekit/Modules.sol";
import { ValidateSignature } from "./VerifySignature/VerifySignature.sol";
import { IntentExecutorBase } from "./IntentExecutorBase.sol";
import { MODULE_TYPE_EXECUTOR } from "modulekit/accounts/common/interfaces/IERC7579Module.sol";
import { Permit2EIP712 } from "@rhinestone/compact-utils/src/common/Permit2EIP712.sol";
import { Permit2IntentExecutor } from "./Permit2Intent/Permit2Executor.sol";
import { StandaloneIntentExecutor } from "./StandaloneIntent/StandaloneIntent.sol";
import { TrustedExecution } from "./TrustedExecution/TrustedExecution.sol";
import { ERC7579InitializedLib } from "./lib/ERC7579InitializedLib.sol";

/**
 * @title IntentExecutor
 * @author Rhinestone (zeroknots.eth, highskore.eth)
 * @notice Main executor contract that unifies multiple intent execution mechanisms
 * @dev This contract serves as the central hub for executing different types of intents:
 *      - CompactIntentExecutor: Executes intents using The Compact protocol for cross-chain transfers
 *      - Permit2IntentExecutor: Executes intents using Permit2 for gasless token approvals
 *      - StandaloneIntentExecutor: Executes intents independently without external protocols
 *      - TrustedExecution: Executes operations from trusted parties without signature verification
 *
 *      The contract inherits from ERC7579ExecutorBase to provide modular account compatibility
 *      and implements the ERC-7579 executor module interface for smart contract wallets.
 *
 * @custom:security This contract aggregates multiple execution paths, each with different trust models.
 *                  Users should understand the security implications of each execution type before use.
 */
contract IntentExecutor is
    ERC7579ExecutorBase,
    IntentExecutorBase,
    ValidateSignature,
    CompactIntentExecutor,
    Permit2IntentExecutor,
    StandaloneIntentExecutor,
    TrustedExecution
{
    using ERC7579InitializedLib for address;
    using ERC7579InitializedLib for bytes32;
    /**
     * @notice Initializes the IntentExecutor with required dependencies for all execution types
     * @dev Chains constructor calls to initialize each inherited executor component:
     *      - CompactIntentExecutor requires router, compact protocol, and lock tag
     *      - Permit2IntentExecutor has no constructor parameters
     *      - StandaloneIntentExecutor looks up Paymaster from AddressBook for gas refunds
     *      - TrustedExecution requires an address book for trusted party validation
     *      - ExecutionSigChecker requires compact protocol
     * @param router The router contract address for cross-chain operations
     * @param compact The Compact protocol contract address for cross-chain transfers
     * @param allocator the RSAllocator
     * @param addressBook The address book contract for managing trusted execution parties
     */

    constructor(
        address router,
        address compact,
        address allocator,
        address addressBook,
        address smartSessionEmissary
    )
        TrustedExecution(addressBook)
        ValidateSignature(compact, smartSessionEmissary)
        CompactEIP712(compact)
        Permit2EIP712(address(Constants.PERMIT2))
        IntentExecutorBase(router, allocator)
        StandaloneIntentExecutor(addressBook)
    { }

    /**
     * @notice Checks if the executor module is initialized for a specific smart account
     * @dev This function is required by the ERC-7579 module interface but currently returns
     *      false as initialization state is not tracked. Future implementations may add
     *      account-specific initialization tracking.
     * @param smartAccount The smart account address to check initialization status for
     * @return bool Always returns false in current implementation
     */
    function isInitialized(address smartAccount) external view returns (bool) {
        return (smartAccount.moduleSlot().get() == 1);
    }

    /**
     * @notice Identifies this contract as an ERC-7579 executor module
     * @dev Part of the ERC-7579 module interface. Returns true only for MODULE_TYPE_EXECUTOR
     *      to indicate this contract implements executor functionality.
     * @param moduleTypeId The module type identifier to check against
     * @return bool True if moduleTypeId matches MODULE_TYPE_EXECUTOR, false otherwise
     */
    function isModuleType(uint256 moduleTypeId) external pure returns (bool) {
        return moduleTypeId == MODULE_TYPE_EXECUTOR;
    }

    /**
     * @notice Handles module installation on a smart account
     * @dev Required by ERC-7579 but currently performs no initialization logic.
     *      Future implementations may add account-specific setup here.
     */
    function onInstall(
        bytes calldata /* data*/
    )
        external
    {
        address account = msg.sender;
        account.moduleSlot().set(1);
    }

    /**
     * @notice Handles module uninstallation from a smart account
     * @dev Required by ERC-7579 but currently performs no cleanup logic.
     *      Future implementations may add account-specific cleanup here.
     */
    function onUninstall(
        bytes calldata /* data*/
    )
        external
    {
        address account = msg.sender;
        account.moduleSlot().set(0);
    }

    function _useTransientReentrancyGuardOnlyOnMainnet() internal view virtual override returns (bool) {
        return false;
    }
}

src/common/CompactEIP712.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

/**
 * @title CompactEIP712
 * @author Rhinestone (zeroknots.eth, highskore.eth)
 * @notice Abstract contract for EIP-712 domain separation and typed data hashing for The Compact protocol
 * @dev This contract provides the foundation for creating and verifying EIP-712 signatures
 *      specifically for The Compact protocol. Unlike Permit2, The Compact uses the full
 *      EIP-712 domain specification including name, version, chainId, and verifyingContract.
 *
 *      The Compact protocol enables cross-chain intent execution with proper domain separation
 *      to prevent signature replay attacks across different chains and contract deployments.
 *
 *      Key features:
 *      - Full EIP-712 domain with version field (v1)
 *      - Immutable domain separator caching for deployment chain
 *      - Support for notarized (cross-chain) signature validation
 *      - Gas-optimized assembly implementations
 *      - Efficient scratch space usage for digest computation
 *
 * @custom:security Domain separators ensure signatures cannot be replayed across chains or contracts
 * @custom:protocol The Compact uses this for intent-based cross-chain execution
 */
abstract contract CompactEIP712 {
    /// @notice The Compact contract address for signature verification
    /// @dev Immutable to ensure consistent domain separation throughout contract lifetime
    address internal immutable COMPACT;

    /// @notice Cached domain separator for the deployment chain
    /// @dev Pre-computed at deployment for gas efficiency on the primary chain
    bytes32 private immutable COMPACT_DOMAINSEPARATOR;

    /// @notice EIP-712 domain type hash: keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)")
    /// @dev Standard EIP-712 domain with all four fields (includes version unlike Permit2)
    bytes32 internal constant _COMPACT_DOMAIN_TYPEHASH = 0x8b73c3c69bb8fe3d512ecc4cf759cc79239f7b179b0ffacaa9a75d522b39400f;

    /// @notice Hash of The Compact protocol name: keccak256(bytes("The Compact"))
    /// @dev Used in EIP-712 domain separator computation
    bytes32 internal constant _NAME_HASH = 0x5e6f7b4e1ac3d625bac418bc955510b3e054cb6cc23cc27885107f080180b292;

    /// @notice Hash of the protocol version: keccak256("1")
    /// @dev Version "1" indicates the first iteration of The Compact protocol
    bytes32 internal constant _VERSION_HASH = 0xc89efdaa54c0f20c7adf612882df0950f5a951637e0307cdcb4c672f298b8bc6;

    /**
     * @notice Initializes The Compact EIP-712 domain parameters
     * @dev Caches the domain separator for the deployment chain to save gas on subsequent calls.
     *      The cached separator is used when validating signatures on the same chain where
     *      the contract was deployed.
     *
     * @param compact The address of The Compact contract for signature verification
     */
    constructor(address compact) {
        COMPACT = compact;
        COMPACT_DOMAINSEPARATOR = _compactDomainSeparator(block.chainid);
    }

    /**
     * @notice Returns the cached domain separator for the deployment chain
     * @dev Gas-efficient getter that returns the pre-computed domain separator.
     *      This should be used for same-chain signature validation.
     *
     * @return The domain separator for the chain where this contract was deployed
     *
     * @custom:gas Minimal gas cost as it returns an immutable value
     */
    function _compactDomainSeparator() internal view virtual returns (bytes32) {
        return COMPACT_DOMAINSEPARATOR;
    }

    /**
     * @notice Computes the EIP-712 typed data hash for the deployment chain
     * @dev Creates the final digest for signature verification using the cached domain separator.
     *      This is the primary function for same-chain signature validation.
     *
     *      The digest is computed as:
     *      keccak256("\x19\x01" || domainSeparator || structHash)
     *
     *      Assembly optimization details:
     *      - Uses scratch space (0x00-0x5A) to avoid memory allocation
     *      - Stores "\x19\x01" prefix at 0x18-0x19 (shifted for alignment)
     *      - Places domain separator at 0x1A-0x39
     *      - Places struct hash at 0x3A-0x59
     *      - Hashes 66 bytes (0x42) starting from 0x18
     *      - Clears position 0x3A after use (defensive cleanup)
     *
     * @param structHash The hash of the structured data to be signed
     * @return digest The final EIP-712 digest for the deployment chain
     *
     * @custom:gas ~200 gas (just keccak256, no domain computation)
     * @custom:usage Primary function for validating signatures created on the same chain
     */
    function _compactHashTypedData(bytes32 structHash) internal view virtual returns (bytes32 digest) {
        digest = _compactDomainSeparator();
        assembly ("memory-safe") {
            // Compute the digest.
            mstore(0x00, 0x1901000000000000) // Store "\x19\x01".
            mstore(0x1a, digest) // Store the domain separator.
            mstore(0x3a, structHash) // Store the struct hash.
            digest := keccak256(0x18, 0x42)
            // Restore the part of the free memory slot that was overwritten.
            mstore(0x3a, 0)
        }
    }

    /**
     * @notice Computes the EIP-712 typed data hash for a notarized (cross-chain) signature
     * @dev Creates the final digest for cross-chain signature verification by computing
     *      the domain separator for the specified chain.
     *
     *      This enables The Compact protocol to validate signatures that were created
     *      on different chains, essential for cross-chain intent execution.
     *
     *      Uses the same assembly optimization pattern as the same-chain version but
     *      computes the domain separator dynamically for the notarized chain.
     *
     * @param structHash The hash of the structured data to be signed
     * @param notarizedChainId The chain ID where the signature was created
     * @return digest The final EIP-712 digest for cross-chain validation
     *
     * @custom:gas ~1000 gas (domain separator computation + keccak256)
     * @custom:security Critical for validating cross-chain intents in The Compact protocol
     */
    function _compactHashTypedData(bytes32 structHash, uint256 notarizedChainId) internal view virtual returns (bytes32 digest) {
        digest = _compactDomainSeparator(notarizedChainId);
        assembly ("memory-safe") {
            // Compute the digest.
            mstore(0x00, 0x1901000000000000) // Store "\x19\x01".
            mstore(0x1a, digest) // Store the domain separator.
            mstore(0x3a, structHash) // Store the struct hash.
            digest := keccak256(0x18, 0x42)
            // Restore the part of the free memory slot that was overwritten.
            mstore(0x3a, 0)
        }
    }

    /**
     * @notice Computes the domain separator for a specific chain ID
     * @dev Dynamically calculates the EIP-712 domain separator for cross-chain signature validation.
     *      This is essential for The Compact's cross-chain intent execution capabilities.
     *
     *      The domain separator is computed as:
     *      keccak256(abi.encode(DOMAIN_TYPEHASH, NAME_HASH, VERSION_HASH, chainId, compactAddress))
     *
     *      Assembly implementation details:
     *      - Uses allocated memory (via mload(0x40)) for the domain struct
     *      - Stores 5 words sequentially: typehash, name, version, chainId, verifyingContract
     *      - Hashes 160 bytes (0xA0) to produce the domain separator
     *
     * @param notarizedChainId The chain ID for which to compute the domain separator
     * @return notarizedDomainSeparator The computed domain separator for the specified chain
     *
     * @custom:gas ~900 gas for computation (keccak256 + memory operations)
     * @custom:protocol Used for validating intents created on different chains
     */
    function _compactDomainSeparator(uint256 notarizedChainId) internal view returns (bytes32 notarizedDomainSeparator) {
        address compact = address(COMPACT);

        assembly ("memory-safe") {
            // Retrieve the free memory pointer.
            let m := mload(0x40)

            // Prepare domain data: EIP-712 typehash, name hash, version hash, notarizing chain ID,
            // and verifying contract.
            mstore(m, _COMPACT_DOMAIN_TYPEHASH)
            mstore(add(m, 0x20), _NAME_HASH)
            mstore(add(m, 0x40), _VERSION_HASH)
            mstore(add(m, 0x60), notarizedChainId)
            mstore(add(m, 0x80), compact)

            // Derive the domain separator.
            notarizedDomainSeparator := keccak256(m, 0xa0)
        }
    }
}

src/executor/CompactIntent/CompactIntent.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

import { ICompactIntentExecutor } from "../interfaces/ICompactIntent.sol";
import { Execution } from "modulekit/integrations/ERC7579Exec.sol";
import { ValidateSignature } from "../VerifySignature/VerifySignature.sol";
import { IntentExecutorNonceLib } from "../lib/IntentExecutorNonceLib.sol";
import { EIP712TypeHashLib } from "@rhinestone/compact-utils/src/types/EIP712TypeHashLib.sol";
import { SmartExecutionLib } from "@rhinestone/compact-utils/src/common/SmartExecutionLib.sol";
import { Bytes32ArrayLib } from "@rhinestone/compact-utils/src/common/Bytes32ArrayLib.sol";
import { Types } from "@rhinestone/compact-utils/src/types/OrderTypes.sol";
import { LibERC7579 } from "@rhinestone/compact-utils/src/common/LibERC7579.sol";
import { CompactEIP712 } from "@rhinestone/compact-utils/src/common/CompactEIP712.sol";
import { IntentExecutorBase } from "../IntentExecutorBase.sol";
import { ConsumeNonceLib } from "../lib/ConsumeNonceLib.sol";
import { ReentrancyGuardTransient } from "solady/utils/ReentrancyGuardTransient.sol";

/**
 * @title CompactIntentExecutor
 * @author Rhinestone (zeroknots.eth, highskore.eth)
 * @notice Executor contract for cross-chain intents using The Compact protocol
 * @dev This contract enables secure cross-chain intent execution through a two-phase process:
 *
 *      Phase 1 (Origin Chain): executePreClaimOpsWithCompactStub
 *      - User signs an EIP-712 structured intent specifying cross-chain operations
 *      - Arbiter calls this function to execute pre-claim operations (e.g., token approvals)
 *      - Contract validates signature and computes claim hash for cross-chain verification
 *      - Sets signature skip permission for the arbiter to execute target operations
 *
 *      Phase 2 (Destination Chain): executeTargetOpsWithCompactStub
 *      - Arbiter provides proof of origin chain execution via claim hash
 *      - Contract validates the claim hash through The Compact protocol's verification system
 *      - If valid, executes the target operations on behalf of the user
 *
 * @custom:security The security model relies on:
 *                  - EIP-712 signatures for user authorization
 *                  - The Compact protocol's cross-chain verification system
 *                  - Router-only access control for cross-chain operations
 *                  - Expiration timestamps to prevent stale execution
 */
abstract contract CompactIntentExecutor is
    ICompactIntentExecutor,
    CompactEIP712,
    IntentExecutorBase,
    ValidateSignature,
    ReentrancyGuardTransient
{
    using Bytes32ArrayLib for bytes32[];
    using SmartExecutionLib for Types.Operation;
    using ConsumeNonceLib for bytes32;
    using IntentExecutorNonceLib for uint256;
    using EIP712TypeHashLib for Types.Operation;

    /**
     * @notice Executes target operations on the destination chain with claim hash verification
     * @dev This function implements the second phase of cross-chain intent execution. It:
     *      1. Reconstructs the element hash from the provided stub data
     *      2. Validates that execution is happening on the correct target chain
     *      3. Checks that the fill hasn't expired
     *      4. Builds the complete Compact Merkle tree with all elements
     *      5. Computes the final EIP-712 claim hash
     *      6. Verifies the claim hash proof through the designated proofer contract
     *      7. Executes the target operations if all validations pass
     * @param account The recipient account address for the target operations
     * @param notarizedArbiter The arbiter address that notarized the cross-chain transfer
     * @param compactStub Core Compact order data (nonce, expires, notarized chain)
     * @param elementStub Element-specific data needed for destination chain execution
     * @param targetOps Array of operations to execute on the destination chain
     * @param signature EIP-712 signature authorizing the target operations
     * @return claimHash The computed claim hash used for verification
     */
    function executeTargetOpsWithCompactStub(
        address account,
        address notarizedArbiter,
        EIP712CompactStub calldata compactStub,
        EIP712ElementStubDestination calldata elementStub,
        Types.Operation calldata targetOps,
        bytes calldata signature
    )
        external
        onlyRouter
        returns (bytes32 claimHash)
    {
        claimHash = _compactClaimHash({
            account: account, notarizedArbiter: notarizedArbiter, compactStub: compactStub, elementStub: elementStub, targetOps: targetOps
        });

        // consume nonce
        compactStub.nonce.compactNonceSlot(account).consumeNonce();

        // recreate Compact Digest for notarized chain
        bytes32 digest = _compactHashTypedData(claimHash, compactStub.notarizedChainId);

        // Validate the signature using the execution signature checker
        require(_isValidSignature(account, LOCKTAG, digest, claimHash, targetOps, signature), InvalidSignature());

        // Execute the target operations on behalf of the account
        LibERC7579.executeOps(account, targetOps);
    }

    /**
     * @notice Executes pre-claim operations on the origin chain before cross-chain transfer
     * @dev This function implements the first phase of cross-chain intent execution. It:
     *      1. Reconstructs the element hash using the caller as the arbiter
     *      2. Builds the complete Compact Merkle tree with all elements
     *      3. Computes the final EIP-712 claim hash
     *      4. Executes the pre-claim operations after signature validation
     *      5. Sets the signature skip flag for corresponding target operations
     * @param account The smart account address that owns the assets and signed the order
     * @param compactStub Core Compact order data (nonce, expires, notarized chain)
     * @param elementStub Element-specific data needed for origin chain execution
     * @param preClaimOps Array of operations to execute before cross-chain transfer (e.g., token approvals)
     * @param signature EIP-712 signature from the account authorizing these operations
     * @return sigOk True if the signature validation passed
     * @return execOk True if the pre-claim operations executed successfully
     */
    function executePreClaimOpsWithCompactStub(
        address account,
        EIP712CompactStub calldata compactStub,
        EIP712ElementStubOrigin calldata elementStub,
        Types.Operation calldata preClaimOps,
        bytes calldata signature
    )
        external
        nonReentrant
        returns (bool sigOk, bool execOk)
    {
        // Reconstruct the element hash with the caller as the arbiter
        // The arbiter is responsible for facilitating the cross-chain transfer
        bytes32 elementHash = EIP712TypeHashLib.hashElementRaw({
            arbiter: msg.sender,
            originChainId: block.chainid,
            tokenInHash: elementStub.tokenInHash,
            mandateHash: EIP712TypeHashLib.hashMandateRaw({
                targetAttributes: elementStub.targetAttributesHash,
                minGas: elementStub.minGas,
                preClaimOpsHash: preClaimOps.hashOps(),
                destOpsHash: elementStub.destOpsHash,
                qHash: elementStub.qHash
            })
        });

        // Insert the computed `elementHash` into the `otherElements` array at the specified `elementOffset`.
        // This builds the complete list of elements for the Compact Merkle tree.
        // Note: `elementOffset` handling differs from TheCompact; here, 0 is notarized, 1 is first exogenous.
        bytes32 allElementsHash = elementStub.otherElements.insertAtAndHash({ index: elementStub.elementOffset, element: elementHash });

        // Compute the final EIP-712 claim hash for the entire Compact order.
        bytes32 claimHash = EIP712TypeHashLib.hashCompact({
            sponsor: account, nonce: compactStub.nonce, expires: compactStub.expires, allElementsHash: allElementsHash
        });

        bytes32 digest = _compactHashTypedData(claimHash, compactStub.notarizedChainId);
        // Validate the signature using the execution signature checker
        sigOk = _isValidSignature(account, LOCKTAG, digest, claimHash, preClaimOps, signature);
        // Early return if signature validation fails
        if (!sigOk) return (false, false);

        // consume nonce
        compactStub.nonce.compactNonceSlot(account).consumeNonce();

        execOk = LibERC7579.tryExecuteOps(account, preClaimOps);
    }

    /**
     * @notice Internal function to compute the claim hash for destination chain execution
     * @dev This function reconstructs the complete claim hash that was originally computed during
     *      pre-claim operations on the origin chain. The hash must match exactly to validate
     *      that the cross-chain intent execution is legitimate. The process involves:
     *
     *      1. Computing the element hash from all individual components
     *      2. Building the complete Compact Merkle tree structure
     *      3. Computing the final EIP-712 claim hash
     *
     *      Critical: All hash components must match the original computation exactly
     *
     * @param account The recipient account address for the target operations
     * @param notarizedArbiter The arbiter address that facilitated the cross-chain transfer
     * @param compactStub Core Compact order data from the origin chain
     * @param elementStub Element-specific data needed for hash reconstruction
     * @param targetOps The operations to execute on this destination chain
     * @return claimHash The computed claim hash for verification
     */
    function _compactClaimHash(
        address account,
        address notarizedArbiter,
        EIP712CompactStub calldata compactStub,
        EIP712ElementStubDestination calldata elementStub,
        Types.Operation calldata targetOps
    )
        internal
        view
        returns (bytes32 claimHash)
    {
        // Ensure the fill operation hasn't expired
        require(elementStub.fillExpires >= block.timestamp, InvalidParams());
        // Reconstruct the element hash by combining all element components
        // This hash must match the one computed during pre-claim operations
        bytes32 targetAttributesHash =
            EIP712TypeHashLib.hashTargetAttributesRaw(account, elementStub.tokenOutHash, block.chainid, elementStub.fillExpires);

        bytes32 mandateHash = EIP712TypeHashLib.hashMandateRaw({
            targetAttributes: targetAttributesHash,
            minGas: 0, // Default for target operations
            preClaimOpsHash: elementStub.preClaimOpsHash,
            destOpsHash: targetOps.hashOps(),
            qHash: elementStub.qHash
        });

        bytes32 elementHash = EIP712TypeHashLib.hashElementRaw({
            arbiter: notarizedArbiter,
            originChainId: compactStub.notarizedChainId,
            tokenInHash: elementStub.tokenInHash,
            mandateHash: mandateHash
        });

        // Insert the computed `elementHash` into the `otherElements` array at the specified `elementOffset`.
        // This builds the complete list of elements for the Compact Merkle tree.
        // Note: `elementOffset` handling differs from TheCompact; here, 0 is notarized, 1 is first exogenous.
        bytes32 allElementsHash = elementStub.otherElements.insertAtAndHash({ index: elementStub.elementOffset, element: elementHash });

        // Compute the final EIP-712 claim hash for the entire Compact order.
        claimHash = EIP712TypeHashLib.hashCompact({
            sponsor: elementStub.sponsor, nonce: compactStub.nonce, expires: compactStub.expires, allElementsHash: allElementsHash
        });
    }

    /**
     * @notice Checks if a nonce has been used for a specific account
     * @dev This function provides a clean way to check nonce usage without relying on low-level storage access
     * @param nonce The nonce value to check
     * @param account The account address that owns the nonce
     * @return used True if the nonce has been consumed, false otherwise
     */
    function isCompactIntentNonceConsumed(uint256 nonce, address account) external view returns (bool used) {
        return nonce.compactNonceSlot(account).isConsumed();
    }
}

src/types/Constants.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

import { AddressBookLib } from "../common/AddressBook/IAddressBook.sol";
import { ISignatureTransfer } from "permit2/src/interfaces/ISignatureTransfer.sol";

/**
 * @title Constants
 * @notice Protocol-wide constants for the Compact cross-chain intent system
 * @dev Contains immutable addresses, hash constants, and address book identifiers
 *      used throughout the protocol for consistency and gas optimization
 */
library Constants {
    /// @notice Uniswap's Permit2 contract address (same on all chains)
    ISignatureTransfer internal constant PERMIT2 = ISignatureTransfer(address(0x000000000022D473030F116dDEE9F6B43aC78BA3));

    /**
     * @notice Hash representing empty execution data
     * @dev keccak256 of empty bytes - used when there are no operations to execute.
     *      This is the hash of an empty Ops[] array in the EIP-712 structure.
     */
    bytes32 internal constant NO_EXEC = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    /**
     * @notice Hash representing an empty Op wrapper struct
     * @dev This is the EIP-712 hash of Op(bytes32(0), []) - an empty operation wrapper.
     *      Used when originOps or destOps in a Mandate is empty.
     *      Computed as: keccak256(abi.encode(TYPEHASH_OP, bytes32(0), NO_EXEC))
     *      Different from NO_EXEC because it includes the Op wrapper typehash.
     */
    bytes32 internal constant NO_OPS = 0x0c7bea50822ae8a3846eccbda4961a80e1e08aa92f2bf046be0011514ad2ddf1;

    /// @notice Sentinel address representing native token (ETH/MATIC/etc.)
    address internal constant NATIVE_TOKEN = address(0);

    /// @notice Default adapter tag when no specific tag is required
    bytes12 internal constant DEFAULT_ADAPTER_TAG = bytes12(0);

    /**
     * @notice EIP-712 hash for empty token input arrays
     * @dev Matches keccak256(abi.encodePacked(new bytes32[](0)))
     *      Same value as NO_EXEC since both represent empty arrays
     */
    bytes32 internal constant EMPTY_TOKEN_IN_HASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    /**
     * @notice EIP-712 hash for empty token output arrays
     * @dev Matches keccak256(abi.encodePacked(new bytes32[](0)))
     *      Same value as NO_EXEC since both represent empty arrays
     */
